package agent

import (
	"context"
	"time"
)

type Binding struct {
	ChannelID   string `json:"channel_id"`
	PublisherID string `json:"publisher_id"`
}
type Region struct {
	ID          string    `json:"id"`
	Name        string    `json:"name"`
	WorkspaceID string    `json:"workspace_id"`
	Sensors     []Binding `json:"sensors"`
	Executors   []string  `json:"executors"`
	// This threshold is an explicit site policy, never generated by a model.
	SoilMoistureMin       *float64 `json:"soil_moisture_min,omitempty"`
	IrrigationDurationMin *float64 `json:"irrigation_duration_min,omitempty"`
}
type Registry struct {
	Version string   `json:"version"`
	Regions []Region `json:"regions"`
}
type Evidence struct {
	ID          string    `json:"id"`
	ChannelID   string    `json:"channel_id"`
	PublisherID string    `json:"publisher_id"`
	Metric      string    `json:"metric"`
	Value       float64   `json:"value"`
	Unit        string    `json:"unit"`
	ObservedAt  time.Time `json:"observed_at"`
}
type Knowledge struct {
	ID      string   `json:"id"`
	Source  string   `json:"source"`
	Text    string   `json:"text"`
	Metrics []string `json:"metrics"`
}
type Finding struct {
	Kind        string   `json:"kind"`
	Explanation string   `json:"explanation"`
	EvidenceIDs []string `json:"evidence_ids"`
}
type Assessment struct {
	RegionID       string    `json:"region_id"`
	MappingVersion string    `json:"mapping_version"`
	Findings       []Finding `json:"findings"`
	KnowledgeIDs   []string  `json:"knowledge_ids"`
}
type Trace struct {
	Step   string `json:"step"`
	Detail string `json:"detail"`
}
type Task struct {
	TaskID         string         `json:"task_id"`
	TraceID        string         `json:"trace_id"`
	TaskType       string         `json:"task_type"`
	Target         string         `json:"target"`
	Params         map[string]any `json:"params"`
	Source         string         `json:"source"`
	WorkspaceID    string         `json:"workspace_id"`
	MappingVersion string         `json:"mapping_version"`
	ExecutorIDs    []string       `json:"executor_ids"`
}
type Result struct {
	AnalysisID     string       `json:"analysis_id"`
	WorkspaceID    string       `json:"workspace_id"`
	RegionID       string       `json:"region_id"`
	MappingVersion string       `json:"mapping_version"`
	CreatedAt      time.Time    `json:"created_at"`
	Mode           string       `json:"mode"`
	Status         string       `json:"status"`
	Evidence       []Evidence   `json:"evidence"`
	Knowledge      []Knowledge  `json:"knowledge"`
	Assessments    []Assessment `json:"assessments"`
	Tasks          []Task       `json:"tasks"`
	Trace          []Trace      `json:"trace"`
	registryHash   string
}
type Request struct {
	WorkspaceID    string `json:"workspace_id"`
	RegionID       string `json:"region_id"`
	MappingVersion string `json:"mapping_version"`
}
type Source interface {
	Read(context.Context, string, Binding, time.Time) ([]Evidence, error)
}
type Analyst interface {
	Analyze(context.Context, string, Region, string, []Evidence, []Knowledge) (Assessment, error)
}
